fn zungqr_c64_short_a() { let v_tau: Vec<Complex64> = (0..(M)).map(|_| Complex64::new(1.0, 0.0)).collect(); let r = at_guard::<Complex64, _>((M*N) - 1, |i| if i % (N + 1) == 0 { Complex64::new(1.0, 0.0) } else { Complex64::new(0.0, 0.0) }, |a| zungqr(M, M, M, a, N, &v_tau)); report("zungqr_c64_short_a", r.map(|_| ())); }
#[test]
fn zungqr_c64_short_tau() { let mut v_a: Vec<Complex64> = (0..(M*N)).map(|i| if i % (N + 1) == 0 { Complex64::new(1.0, 0.0) } else { Complex64::new(0.0, 0.0) }).collect(); let r = at_guard::<Complex64, _>((M) - 1, |_| Complex64::new(1.0, 0.0), |tau| zungqr(M, M, M, &mut v_a, N, tau)); report("zungqr_c64_short_tau", r.map(|_| ())); }
